/// <summary>
/// Base class for PricingAttribute table <c>METCustTable</c>
/// </summary>
public abstract class METGUPPricingAttributeMETCustTable extends GUPAbstractPricingAttribute implements GUPIPricingAttribute
{
}

Method.Source:
    /// <summary>
    /// Get table record of METCustTable
    /// </summary>
    /// <param name="_pricingObject">
    /// The <c>Common</c> object that will be used to get the table record
    /// </param>
    /// <returns><c>METCustTable</c> object</returns>
    protected METCustTable getTableRecord(Common _pricingObject)
    {
        METCustTable metCustTable;
        SalesTable  salesTable = _pricingObject as SalesTable;

        if (salesTable)
        {
            metCustTable = METCustTable::find(salesTable.CustAccount);
        }

        return metCustTable;
    }

/// <summary>
/// Get value datasource identifier table string
/// </summary>
/// <returns>table name string</returns>
public str getQueryBuilderDatasourceIdentifier()
{
    return tableStr(METCustTable);
}

    /// <summary>
    /// Get value query build datasource object
    /// </summary>
    /// /// <param name="_query">
    /// The <c>Query</c> object that will be used to generate query datasource
    /// </param>
    /// /// <param name="_qbdsMap">
    /// The <c>Map</c> object that will be used to manage customer
    /// </param>
    /// <returns><c>QueryBuildDataSource</c> object</returns>
    protected QueryBuildDataSource getQueryBuildDatasource(Query _query, Map _qbdsMap = null)
    {
        QueryBuildDataSource qbdsRoot, qbdsMetCustTable;

        if (_qbdsMap && _qbdsMap.exists(tableStr(CustTable)))
        {
            qbdsRoot = _qbdsMap.lookup(tableStr(CustTable));
        }
        else
        {
            qbdsRoot = _query.addDataSource(tableNum(CustTable));

            if (_qbdsMap)
            {
                _qbdsMap.insert(tableStr(CustTable), qbdsRoot);
            }
        }

        if (_qbdsMap && _qbdsMap.exists(tableStr(METCustTable)))
        {
            qbdsMetCustTable = _qbdsMap.lookup(tableStr(METCustTable));
        }
        else
        {
            qbdsMetCustTable = qbdsRoot.addDataSource(tableNum(METCustTable));
            qbdsMetCustTable.addLink(fieldNum(CustTable, AccountNum), fieldNum(METCustTable, AccountNum));
            qbdsMetCustTable.joinMode(JoinMode::ExistsJoin);

            if (_qbdsMap)
            {
                _qbdsMap.insert(tableStr(METCustTable), qbdsMetCustTable);
            }
        }

        return qbdsMetCustTable;
    }

    /// <summary>
    /// Builds pricing object query
    /// </summary>
    /// <param name="_query">
    /// The <c>Query</c> object that the new ranges will be added to.
    /// </param>
    /// <param name="_value">
    /// The <c>anytype</c> object that determines the customer.
    /// </param>
    /// <param name="_qdbsMap">
    /// The <c>Map</c> object that is used to identify the query build data source.
    /// </param>
    /// <returns><c>Query</c> object</returns>
    public Query buildPricingObjectQuery(Query _query, anytype _value, Map _qdbsMap = null)
    {
        QueryBuildDataSource qbds;

        qbds = this.getQueryBuildDatasource(_query, _qdbsMap);
        this.setQueryBuildDatasourceRange(qbds, _value);

        return _query;
    }

/// <summary>
/// Gets the path of the attribute tables
/// </summary>
/// <returns><c>GUPPricingAttributeTableFieldPath</c> object</returns>
public GUPPricingAttributeTableFieldPath getPath()
{
    return strFmt('%1#%2_%3$%4#%5_%6$%7#%8',
        tableStr(SalesTable),
        tableStr(CustTable),
        fieldStr(SalesTable, CustAccount),
        fieldStr(CustTable, AccountNum),
        tableStr(METCustTable),
        fieldStr(CustTable, AccountNum),
        fieldStr(METCustTable, AccountNum),
        this.getAttributeFieldIdentifier());
}

/// <summary>
/// Get the table name
/// </summary>
/// <returns>
/// Returns a TableName object
/// </returns>
public TableName getTableName()
{
    return tableStr(METCustTable);
}
